'use strict';
const $=s=>document.querySelector(s),fields={player:'Current player',bid:'Current bid',bidder:'Leading team',sold:'Sold status text',timer:'Timer (optional)',resultRow:'Result row',resultPlayer:'Result player',resultTeam:'Winning team',resultAmount:'Final price',logRow:'Bid history row',logPlayer:'Bid player',logTeam:'Bidding team',logAmount:'Bid amount'};
async function call(type,args={}){const result=await chrome.runtime.sendMessage({type,...args});if(result?.error)throw Error(result.error);return result;}
async function render(){const c=await call('get');$('#status').classList.remove('error');$('#status').textContent=(c.status.ready&&c.status.at&&Date.now()-c.status.at<5000?'Watching selected fields':c.watching?'Setup incomplete':'Paused / disconnected')+' · '+c.queue+' queued updates\n'+c.status.message;$('#pause').textContent=c.watching?'Pause capture':'Resume capture';$('#selectors').value=JSON.stringify(c.selectors,null,2);for(const [target,keys] of [['fields',['player','bid','bidder','sold','timer']],['result-fields',['resultRow','resultPlayer','resultTeam','resultAmount']],['log-fields',['logRow','logPlayer','logTeam','logAmount']]]){const parent=document.getElementById(target);parent.replaceChildren();for(const k of keys){const row=document.createElement('div'),button=document.createElement('button'),label=document.createElement('span');row.className='field';button.textContent=fields[k];button.dataset.pick=k;label.textContent=c.selectors[k]?'Selected ✓':'Not selected';label.className=c.selectors[k]?'set':'';label.title=c.selectors[k]||'';row.append(button,label);parent.append(row);}}}
function error(e){$('#status').classList.add('error');$('#status').textContent=e.message;}
document.addEventListener('click',async e=>{try{const id=e.target.id,pick=e.target.dataset.pick;if(pick){await call('pick',{field:pick});window.close();return;}if(['pair','watch'].includes(id)){const [tab]=await chrome.tabs.query({active:true,currentWindow:true});const url=new URL(tab.url);if(!['https:','http:'].includes(url.protocol))throw Error('Open the Survivor site or Yahoo draft tab first.');const granted=await chrome.permissions.request({origins:[url.origin+'/*']});if(!granted)throw Error('Access to this selected site is needed to read its draft fields.');await call(id,{tabId:tab.id});}if(id==='pause')await call('pause');if(id==='clear'){if(!confirm('Discard queued draft updates? Export your Survivor session first.'))return;await call('clear');}if(id==='save-selectors')await call('selectors',{selectors:JSON.parse($('#selectors').value)});if(['pair','watch','pause','refresh','clear','save-selectors'].includes(id))await render();}catch(e){error(e);}});
render().catch(error);
